    // Check if n can be represented as x^a + y^b for non-negative integers a, b
    // We need to check all possible values of x^a and y^b that are <= n

    // Generate all powers of x that are <= n
    $powersX = [];
    $val = 1;
    while ($val <= $n) {
        $powersX[] = $val;
        if ($val > $n / $x) break;
        $val *= $x;
    }

    // Generate all powers of y that are <= n
    $powersY = [];
    $val = 1;
    while ($val <= $n) {
        $powersY[] = $val;
        if ($val > $n / $y) break;
        $val *= $y;
    }

    // For each power of x, check if n - powerX is a power of y
